<script setup lang="ts">
import {computed, ref, watch} from 'vue'
import {locale,t} from '../lib/i18n'
import {asset} from '../lib/assets'
const emit=defineEmits<{close:[];security:[]}>()
const view=ref<'settings'|'language'|'notifications'|'privacySettings'|'general'>('settings')
const confirm=ref(false),notice=ref('')
const defaults={notifications:true,incoming:true,replies:true,system:true,haptics:true,recommendations:true,systemFont:false}
const preferences=ref({...defaults,...JSON.parse(localStorage.getItem('maugo-settings')||'{}')})
watch(preferences,v=>{localStorage.setItem('maugo-settings',JSON.stringify(v));document.documentElement.classList.toggle('system-font',v.systemFont)},{deep:true,flush:'sync'})
const categories=['incoming','replies','system'] as const
const generalItems=['haptics','recommendations','systemFont'] as const
const pages=[['privacySettings','08-interface-icons/icon-shield-lime-22'],['notifications','08-interface-icons/icon-bell-lime-22'],['general','08-interface-icons/icon-settings-light-24'],['language','08-interface-icons/icon-globe-lime-22']] as const
const title=computed(()=>t(view.value))
function back(){if(confirm.value)confirm.value=false;else if(view.value==='settings')emit('close');else{view.value='settings';notice.value=''}}
function cleared(){confirm.value=false;notice.value=t('cacheCleared')}
</script>
<template>
<section class="settings-flow" @keydown.esc.stop="back">
<header><button id="settings-back" :aria-label="t('back')" @click="back"><img :src="asset('08-interface-icons/icon-chevron-left-light-settings-22')" alt=""></button><h1>{{title}}</h1><span></span></header>
<Transition name="settings-page" mode="out-in"><div :key="view" class="settings-body">
<template v-if="view==='settings'"><div class="settings-group"><button id="security-settings" class="settings-row" @click="emit('security')"><img :src="asset('08-interface-icons/icon-lock-lime-22')" alt=""><span>Account &amp; security</span><b>›</b></button><button v-for="[page,icon] in pages" :key="page" :id="`${page}-settings`" class="settings-row" @click="view=page"><img :src="asset(icon)" alt=""><span>{{t(page)}}</span><small v-if="page==='language'">{{locale==='en'?'English':'한국어'}}</small><b aria-hidden="true">›</b></button></div></template>
<template v-else-if="view==='language'"><p>{{t('chooseLanguage')}}</p><div class="language-options"><button v-for="lang in ['en','ko'] as const" :key="lang" :data-language="lang" :aria-pressed="locale===lang" @click="locale=lang"><span>{{lang==='en'?'English':'한국어'}}</span><b>{{locale===lang?'✓':''}}</b></button></div></template>
<template v-else-if="view==='notifications'"><div class="settings-group"><label class="settings-row"><span>{{t('allowNotifications')}}</span><input id="allow-notifications" v-model="preferences.notifications" type="checkbox" role="switch"><i aria-hidden="true"></i></label><label v-for="item in categories" :key="item" class="settings-row" :class="{'category-disabled':!preferences.notifications}"><span>{{t(item)}}</span><input :id="`${item}-notifications`" v-model="preferences[item]" type="checkbox" role="switch" :disabled="!preferences.notifications"><i aria-hidden="true"></i></label></div></template>
<template v-else-if="view==='privacySettings'"><div class="settings-group"><button id="profile-visibility" class="settings-row" disabled><span>{{t('profileVisibility')}}</span><small>{{t('unavailable')}}</small></button></div><p role="status">{{t('privacyUnavailable')}}</p></template>
<template v-else><div class="settings-group"><label v-for="item in generalItems" :key="item" class="settings-row"><span>{{t(item)}}</span><input :id="item" v-model="preferences[item]" type="checkbox" role="switch"><i aria-hidden="true"></i></label><button id="clear-cache" class="settings-row" @click="confirm=true;notice=''"><span>{{t('clearCache')}}</span><b aria-hidden="true">›</b></button></div><p>{{t('cacheNote')}}</p><p v-if="notice" role="status">{{notice}}</p></template>
</div></Transition>
<Transition name="settings-dialog"><div v-if="confirm" class="settings-veil" @click.self="confirm=false"><section role="dialog" aria-modal="true" :aria-label="t('cacheConfirm')" class="settings-confirm"><h2>{{t('cacheConfirm')}}</h2><p>{{t('cacheNote')}}</p><button id="confirm-clear-cache" class="primary" @click="cleared">{{t('clearCache')}}</button><button id="cancel-clear-cache" @click="confirm=false">{{t('cancel')}}</button></section></div></Transition>
</section>
</template>
<style scoped>
.settings-flow{position:absolute;inset:0;z-index:35;background:#0d1713;color:#d3e5c9;padding-top:48px;display:flex;flex-direction:column}.settings-flow header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;flex-shrink:0}.settings-flow header button,.settings-flow header>span{width:32px}.settings-flow header button{padding:5px;background:none;display:grid;place-items:center}.settings-flow header img{width:22px;height:22px}.settings-flow h1{font-size:19px;font-weight:500;margin:0}.settings-body{padding:16px 24px 40px;overflow:auto;flex:1}.settings-group{margin-bottom:24px}.settings-row{display:flex;align-items:center;gap:14px;min-height:62px;width:100%;padding:16px 0;border-bottom:1px solid #ffffff0b;background:none;text-align:left;color:#d3e5c9;font-size:14px;position:relative}.settings-row>span{flex:1}.settings-row>img{width:22px;height:22px;object-fit:contain}.settings-row small{color:#8dae7e;font-size:12px}.settings-row>b{font-size:22px;font-weight:400;color:#8dae7e}.settings-body p,.settings-confirm p{font-size:12px;line-height:22px;color:#8dae7e;margin:4px 0 24px}.settings-row input{position:absolute;right:0;width:44px;height:26px;opacity:0;cursor:pointer;margin:0;z-index:1}.settings-row i{width:44px;height:26px;border-radius:20px;background:#354532;transition:background .2s;flex-shrink:0}.settings-row i:after{content:'';display:block;width:20px;height:20px;border-radius:50%;background:#a2b797;margin:3px;transition:transform .2s,background .2s}.settings-row input:checked+i{background:#b5fa70}.settings-row input:checked+i:after{transform:translateX(18px);background:#19362b}.settings-row input:focus-visible+i{outline:2px solid #b5fa70;outline-offset:4px}.category-disabled{opacity:.4}.settings-veil{position:absolute;inset:0;background:#030805b8;backdrop-filter:blur(5px);display:flex;align-items:center;padding:24px;z-index:1}.settings-confirm{width:100%;padding:26px 22px 14px;border:1px solid #ffffff12;border-radius:24px;background:#1c2c22;text-align:center}.settings-confirm h2{font-size:20px;font-weight:500;margin:0 0 16px}.settings-confirm button{display:block;width:100%;min-height:48px;border-radius:24px;margin:10px 0;background:none;color:#b5fa70}.settings-confirm .primary{background:#b5fa70;color:#19362b}.settings-page-enter-active,.settings-page-leave-active{transition:opacity .18s,transform .18s}.settings-page-enter-from{opacity:0;transform:translateX(16px)}.settings-page-leave-to{opacity:0;transform:translateX(-12px)}.settings-dialog-enter-active,.settings-dialog-leave-active{transition:opacity .22s}.settings-dialog-enter-active .settings-confirm,.settings-dialog-leave-active .settings-confirm{transition:transform .22s}.settings-dialog-enter-from,.settings-dialog-leave-to{opacity:0}.settings-dialog-enter-from .settings-confirm,.settings-dialog-leave-to .settings-confirm{transform:translateY(20px) scale(.97)}
</style>
